insert into public.board_questions (subject_id, board, year, question_type, title, content, solution) values
 ('30000000-0000-0000-0000-000000000004','ঢাকা',2024,'cq','ঢাকা বোর্ড ২০২৪ — পদার্থবিজ্ঞান সৃজনশীল','একটি গাড়ি স্থির অবস্থা থেকে 4 m/s² ত্বরণে 10 s চলল।\n(ক) সুষম ত্বরণ কী?\n(খ) গাড়িটির বেগ নির্ণয় কর।','(খ) v = u + at = 0 + 4×10 = 40 m/s'),
 ('30000000-0000-0000-0000-000000000003','রাজশাহী',2023,'cq','রাজশাহী বোর্ড ২০২৩ — সাধারণ গণিত','A = {1,2,3}, B = {2,3,4} হলে A∪B ও A∩B নির্ণয় কর।','A∪B = {1,2,3,4}, A∩B = {2,3}'),
 ('30000000-0000-0000-0000-000000000011','চট্টগ্রাম',2024,'mcq','চট্টগ্রাম বোর্ড ২০২৪ — ICT বহুনির্বাচনি','(1010)₂ এর দশমিক মান কত?','10'),
 ('30000000-0000-0000-0000-000000000005','কুমিল্লা',2023,'cq','কুমিল্লা বোর্ড ২০২৩ — রসায়ন','বোর পরমাণু মডেলের সীমাবদ্ধতা লেখ।','একাধিক ইলেকট্রনযুক্ত পরমাণুর বর্ণালি ব্যাখ্যা করতে পারে না।');
insert into public.questions (id, subject_id, chapter_id, type, body, marks, explanation) values
 ('50000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000004','40000000-0000-0000-0000-000000000001','mcq','SI পদ্ধতিতে মৌলিক রাশি কয়টি?',1,'দৈর্ঘ্য, ভর, সময়, তাপমাত্রা, তড়িৎ প্রবাহ, দীপন তীব্রতা ও পদার্থের পরিমাণ — মোট ৭টি।'),
 ('50000000-0000-0000-0000-000000000002','30000000-0000-0000-0000-000000000004','40000000-0000-0000-0000-000000000001','mcq','কোনটি লব্ধ রাশি?',1,'বেগ = সরণ/সময়, তাই এটি লব্ধ রাশি।'),
 ('50000000-0000-0000-0000-000000000003','30000000-0000-0000-0000-000000000004','40000000-0000-0000-0000-000000000001','mcq','ভরের SI একক কোনটি?',1,'ভরের SI একক কিলোগ্রাম।'),
 ('50000000-0000-0000-0000-000000000004','30000000-0000-0000-0000-000000000004','40000000-0000-0000-0000-000000000002','mcq','স্থির অবস্থা থেকে 2 m/s² ত্বরণে 5 s পরে বেগ কত?',1,'v = u + at = 0 + 2×5 = 10 m/s'),
 ('50000000-0000-0000-0000-000000000005','30000000-0000-0000-0000-000000000004','40000000-0000-0000-0000-000000000003','mcq','F = ma কোন সূত্র থেকে পাওয়া যায়?',1,'নিউটনের দ্বিতীয় গতিসূত্র।'),
 ('50000000-0000-0000-0000-000000000006','30000000-0000-0000-0000-000000000005','40000000-0000-0000-0000-000000000005','mcq','পরমাণুর নিউক্লিয়াস আবিষ্কার করেন কে?',1,'রাদারফোর্ড আলফা কণা বিচ্ছুরণ পরীক্ষায় নিউক্লিয়াস আবিষ্কার করেন।'),
 ('50000000-0000-0000-0000-000000000007','30000000-0000-0000-0000-000000000003','40000000-0000-0000-0000-000000000007','mcq','নিচের কোনটি অমূলদ সংখ্যা?',1,'√2 কে p/q আকারে প্রকাশ করা যায় না।'),
 ('50000000-0000-0000-0000-000000000008','30000000-0000-0000-0000-000000000006','40000000-0000-0000-0000-000000000006','mcq','মানুষের বৈজ্ঞানিক নাম কী?',1,'Homo sapiens।'),
 ('50000000-0000-0000-0000-000000000009','30000000-0000-0000-0000-000000000004','40000000-0000-0000-0000-000000000002','cq',E'একটি গাড়ি স্থির অবস্থা থেকে 3 m/s² সুষম ত্বরণে 8 s চলল।\n(ক) ত্বরণ কাকে বলে?\n(খ) সুষম বেগ ও সুষম ত্বরণের পার্থক্য লেখ।\n(গ) 8 s পর গাড়িটির বেগ ও অতিক্রান্ত দূরত্ব নির্ণয় কর।',10,'(গ) v = 24 m/s, s = ½×3×64 = 96 m'),
 ('50000000-0000-0000-0000-000000000011','30000000-0000-0000-0000-000000000011','40000000-0000-0000-0000-000000000012','mcq','(1010)₂ এর দশমিক মান কত?',1,'8 + 0 + 2 + 0 = 10'),
 ('50000000-0000-0000-0000-000000000012','30000000-0000-0000-0000-000000000011','40000000-0000-0000-0000-000000000012','mcq','হেক্সাডেসিমাল সংখ্যা পদ্ধতির ভিত্তি কত?',1,'ভিত্তি ১৬।'),
 ('50000000-0000-0000-0000-000000000013','30000000-0000-0000-0000-000000000011','40000000-0000-0000-0000-000000000011','mcq','"বিশ্বগ্রাম" ধারণার প্রবর্তক কে?',1,'মার্শাল ম্যাকলুহান।'),
 ('50000000-0000-0000-0000-000000000014','30000000-0000-0000-0000-000000000011','40000000-0000-0000-0000-000000000012','mcq','(15)₁₀ এর বাইনারি রূপ কোনটি?',1,'15 = 8+4+2+1 = 1111');
